// Some portions generated by Claude

package org.eclipse.rdf4j.sail.shacl;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.StringReader;
import java.io.StringWriter;

import org.eclipse.rdf4j.model.Model;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.repository.sail.SailRepositoryConnection;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.eclipse.rdf4j.rio.Rio;
import org.eclipse.rdf4j.sail.Sail;
import org.eclipse.rdf4j.sail.memory.MemoryStore;
import org.eclipse.rdf4j.sail.shacl.results.ValidationReport;
import org.junit.jupiter.api.Test;

/**
 * Validation reports must be serializable when a shape refers to an RDF list whose nodes are IRIs rather than blank
 * nodes (https://github.com/eclipse-rdf/rdf4j/issues/5940).
 */
public class ShaclValidatorIriListReportTest {

	private static final String PREFIXES = "@prefix sh: <http://www.w3.org/ns/shacl#> . "
			+ "@prefix rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#> . "
			+ "@prefix schema: <http://schema.org/> . "
			+ "@prefix ex: <http://example.com/> . ";

	private static final String SHAPES = PREFIXES
			+ "schema:PersonShape a sh:NodeShape ; sh:targetClass schema:Person ; "
			+ "sh:property [ sh:path schema:givenName ; sh:or schema:Or ] . "
			+ "schema:Or rdf:first schema:First ; rdf:rest schema:Rest . "
			+ "schema:Rest rdf:first schema:Second ; rdf:rest () . "
			+ "schema:First sh:class schema:Name . "
			+ "schema:Second sh:class schema:GivenName . ";

	private static final String INVALID_DATA = PREFIXES + "ex:Bob a schema:Person ; schema:givenName \"Bob\" .";

	@Test
	public void reportForShapeWithIriOrListCanBeSerialized() throws Exception {
		var report = ShaclValidator.builder()
				.withShapes(load(SHAPES))
				.build()
				.validate(load(INVALID_DATA));

		assertFalse(report.conforms());

		Model model = report.asModel();

		StringWriter writer = new StringWriter();
		Rio.write(model, writer, RDFFormat.TURTLE);
		assertTrue(writer.toString().contains("conforms"));
	}

	private static Sail load(String turtle) throws Exception {
		SailRepository repository = new SailRepository(new MemoryStore());
		repository.init();
		try (SailRepositoryConnection connection = repository.getConnection()) {
			connection.add(new StringReader(turtle), "", RDFFormat.TURTLE);
		}
		return repository.getSail();
	}
}
